			hint = "Libere al druida dormido del hechizo de los Tuercepinos.",
			text = [=[Con un amuleto arrebatado a los chamanes, Oben encontró la respuesta. Había que matar su cuerpo y usar el amuleto sobre él. Cuando se hizo, su espíritu quedó libre para descansar en el Sueño.]=],
		},
	},
	mentions = {
		{ text = "El druida dormido" },
		{ text = "Druida de la Garra" },
